#!/usr/bin/env node
// Regenerates docs/rules.md from the rule definitions: `node scripts/gen-rules-doc.js`
import fs from 'node:fs';
import { ALL_RULES, ALL_TOOL_RULES } from '../src/index.js';

const section = (title, rules) => [
  `## ${title}`,
  '',
  ...rules.flatMap((r) => [
    `### ${r.id}`,
    '',
    `**\`${r.name}\`** · default severity: **${r.severity}**`,
    '',
    `${r.title}.`,
    '',
    ...(r.description ? [r.description, ''] : []),
    ...(r.fix ? [`**How to fix:** ${r.fix}`, ''] : []),
  ]),
];

const out = [
  '# mcp-warden rules',
  '',
  '<!-- generated by scripts/gen-rules-doc.js – do not edit by hand -->',
  '',
  'Severities can be raised or lowered per finding depending on context (for example, auto-approving a `delete_file` tool is high, auto-approving `list_files` is medium).',
  'Disable any rule with `--ignore <ID or name>`.',
  '',
  ...section('Config rules', ALL_RULES),
  ...section('Tool-poisoning rules', ALL_TOOL_RULES),
].join('\n');

fs.writeFileSync(new URL('../docs/rules.md', import.meta.url), out);
console.log('docs/rules.md updated');
